recolour.by_key_position.primitive_sketch:
K = find_key(inp); T = target_colour
for corr in [row,col,layout_scaled,rank]: out = paint(T-cells, K[corr(cell)])
keep corr matching all pairs; post: erase_key / crop_to_targets as induced

recolour.by_shape_match.primitive_sketch:
ex = objects(not cand colour); for o in objects(cand):
  m = [e for e in ex if canon(o.shape,equiv)==canon(e.shape,equiv)]
  if m: paint(o, m[0].colour)

recolour.by_touching_marker.primitive_sketch:
for t in segment(targets): m = assoc(t, markers, rule)
  paint(t, m.colour); if erase: clear(m)
rule induced by trying contains/adjacent/nearest/ancestor

recolour.by_ordinal_index.primitive_sketch:
els = order(segment(inp, elem), axis, dir)
for i,e in enumerate(els): c = palette[i % k]; if c: paint(e.fg, c)
search elem/axis/dir/k consistent with pairs

fill.region_by_property.primitive_sketch:
R = components(inp==bg or seeds, conn)
for f in FEATURES: g = induce(f); if consistent: break
for r in R: paint(r, g(f(r)))

stamp.template_at_markers.primitive_sketch:
tpl,markers=segment_template_markers(I)
rule,rec,tf=induce_anchor(train)  # search anchor∈{centre,same-colour,offset}
for m in markers: paste(O, tf[m.colour](recolour(tpl,rec,m)), align(rule,tpl,m))
erase(O, erase_set); return O or concat(copies)

stamp.copy_to_congruent_target.primitive_sketch:
src=select_source(I); targets=find_regions(I, same_shape(src, key))
for t in targets: paste(O, recolour(T(src, size=t.size), t), t.origin)
key/T induced by trying keys in order and verifying on train

stamp.panel_copy.primitive_sketch:
P=split_panels(I); src=select(P, rule_src)
for p in select(P, rule_tgt): p[:]=merge(T_idx(src), p, keep_existing, paint)
rules searched over small finite menu, validated on train

ray.full_line.primitive_sketch:
seeds=segment(inp); axis=learn(colour|orient->axis)
for s in seeds: for a in axis(s): paint line(s.anchor,a) within clip(s)
resolve overlaps by learned priority / crossing colour; redraw objects if layer=under
